<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/configs/config.php';
require_once __DIR__ . '/configs/social_schema.php';
if (empty($_SESSION['usuario_id'])) { header('Location: Login.php?redirect=chats.php'); exit; }
ensureSocialSchema($pdo);
$uid = (int)$_SESSION['usuario_id'];
$statement = $pdo->prepare('SELECT nm_usuario,social_handle,foto_perfil,tp_usuario,is_community_user FROM usuario WHERE id_usuario=?');
$statement->execute([$uid]);
$me = $statement->fetch();
if (!$me) { session_destroy(); header('Location: Login.php'); exit; }
$_SESSION['usuario_nome'] = $me['nm_usuario'];
$_SESSION['usuario_tipo'] = $me['tp_usuario'];
$isAdmin = strcasecmp(trim((string)$me['tp_usuario']), 'Administrador') === 0;
$canCreate = $isAdmin || !empty($me['is_community_user']);
if (empty($_SESSION['social_csrf'])) $_SESSION['social_csrf'] = bin2hex(random_bytes(24));
?>
