<script>
const API='ajax/social_api.php',EVENTS='ajax/social_events.php',CSRF=<?= json_encode($_SESSION['social_csrf']) ?>,ME=<?= $uid ?>;
const REQUESTED_CHAT=Number(new URLSearchParams(location.search).get('chat')||0);
let data={communities:[],chats:[]},tab=new URLSearchParams(location.search).get('tab')==='private'?'private':'communities';
let activeChat=0,activeCommunity=null,source=null,timer,messageSync=null,openedRequestedChat=false,editContext=null,replyingTo=null,communityMembers=[],memberView='requests';
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
async function api(action,options={}){const response=await fetch(API+'?'+new URLSearchParams({action,...(options.query||{})}),options.fetch);const result=await response.json().catch(()=>({ok:false,message:'Resposta inválida.'}));if(!response.ok||!result.ok)throw new Error(result.message||'Falha na operação.');return result}
function avatar(photo,name,className='social-avatar'){return photo?`<span class="${className}"><img src="${esc(photo)}" alt="Foto de ${esc(name)}"></span>`:`<span class="${className}" aria-hidden="true">${esc(name?.[0]||'U')}</span>`}
function communityAvatar(community,className='social-avatar'){return community.imagem_capa?`<span class="${className}"><img src="${esc(community.imagem_capa)}" alt="Foto da comunidade ${esc(community.nome)}"></span>`:`<span class="${className}" aria-hidden="true"><i class="fa-solid fa-users"></i></span>`}
function showChatNotice(message,title='LibrasHub'){chatNoticeTitle.textContent=title;chatNoticeMessage.textContent=message;chatNoticeDialog.classList.add('is-open')}
let confirmResolver=null;function askConfirmation(message,title='Confirmar ação'){confirmTitle.textContent=title;confirmMessage.textContent=message;confirmDialog.classList.add('is-open');return new Promise(resolve=>{confirmResolver=resolve})}function closeConfirmation(result=false){confirmDialog.classList.remove('is-open');const resolve=confirmResolver;confirmResolver=null;if(resolve)resolve(result)}confirmDialog.addEventListener('click',event=>{const button=event.target.closest('[data-confirm]');if(!button&&event.target!==confirmDialog)return;closeConfirmation(button?.dataset.confirm==='true')});
function setView(id){['welcome','chatView','communityView'].forEach(view=>document.getElementById(view).classList.toggle('is-active',view===id));chatBack.hidden=id==='welcome';document.querySelector('.social-layout').classList.toggle('has-conversation',id!=='welcome');if(id!=='communityView')communityManageButton.hidden=true}
chatBack.addEventListener('click',()=>{if(source)source.close();clearInterval(messageSync);source=null;messageSync=null;activeChat=0;
activeCommunity=null;clearReply();
chatTitle.textContent=tab==='private'?'Chats privados':'Comunidades';setView('welcome')});

async function overview(){try{data=await api('overview');if(REQUESTED_CHAT&&!openedRequestedChat){const requested=data.chats.find(chat=>Number(chat.id_chat)===REQUESTED_CHAT&&chat.tipo==='privado');if(requested){openedRequestedChat=true;tab='private';renderList();await openChat(Number(requested.id_chat),requested.titulo||'Conversa privada');return}}renderList()}catch(error){socialList.innerHTML=`<div class="social-empty">${esc(error.message)}</div>`}}
function renderList(){document.querySelectorAll('.social-tab').forEach(button=>button.classList.toggle('is-active',button.dataset.list===tab));if(tab==='communities'){socialList.innerHTML=data.communities.length?data.communities.map(community=>`<button class="social-item" type="button" data-community="${community.id_comunidade}">${communityAvatar(community)}<span class="social-item__body"><strong>${esc(community.nome)}</strong><small>${community.privada==1?'Privada':'Pública'} · ${Number(community.membros)} membro(s)</small></span></button>`).join(''):'<div class="social-empty">Nenhuma comunidade encontrada.</div>'}else{const chats=data.chats.filter(chat=>chat.tipo==='privado');socialList.innerHTML=chats.length?chats.map(chat=>`<button class="social-item" type="button" data-chat="${chat.id_chat}">${avatar(chat.foto_perfil,chat.titulo)}<span class="social-item__body"><strong>${esc(chat.titulo||'Conversa privada')}</strong><small>Chat privado</small></span></button>`).join(''):'<div class="social-empty">Busque uma pessoa para iniciar uma conversa.</div>'}}
document.querySelector('.social-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-list]');if(!button)return;tab=button.dataset.list;history.replaceState({},'',`chats.php?tab=${tab}`);chatTitle.textContent=tab==='private'?'Chats privados':'Comunidades';setView('welcome');renderList()});
socialList.addEventListener('click',event=>{const community=event.target.closest('[data-community]'),chat=event.target.closest('[data-chat]');if(community)openCommunity(Number(community.dataset.community));if(chat)openChat(Number(chat.dataset.chat),chat.querySelector('strong').textContent)});

function communityMedia(post){if(!post.midia_url)return '';return post.midia_tipo==='video'?`<video class="community-media" controls preload="metadata"><source src="${esc(post.midia_url)}"></video>`:`<img class="community-media" src="${esc(post.midia_url)}" alt="Mídia publicada por ${esc(post.nm_usuario)}" loading="lazy">`}
function communityRoleBadge(role){if(role==='dono')return '<span class="community-role-badge is-owner"><i class="fa-solid fa-crown"></i>Dono</span>';if(role==='moderador')return '<span class="community-role-badge is-moderator"><i class="fa-solid fa-shield-halved"></i>Moderador</span>';return ''}
function renderCommunityPost(post){const canDelete=Number(post.id_usuario)===ME||Boolean(activeCommunity?.canModerate);return `<article class="social-post community-feed-post ui-card" id="community-post-${Number(post.id_post)}" data-community-post="${Number(post.id_post)}"><div class="social-post__head">${avatar(post.foto_perfil,post.nm_usuario,'post-avatar')}<div><a href="perfil.php?id=${Number(post.id_usuario)}">${esc(post.nm_usuario)}</a>${communityRoleBadge(post.papel_comunidade)}<time>${esc(post.criado_em)}${post.editado_em?' · editado':''}</time></div><div class="post-tools">${Number(post.id_usuario)===ME?'<button type="button" class="post-edit" data-edit-community-post aria-label="Editar publicação"><i class="fa-regular fa-pen-to-square"></i>Editar</button>':''}${canDelete?'<button type="button" class="post-delete" data-delete-community-post aria-label="Excluir publicação"><i class="fa-regular fa-trash-can"></i>Excluir</button>':''}</div></div>${post.conteudo?`<p>${esc(post.conteudo)}</p>`:''}${communityMedia(post)}<footer class="community-post-actions"><button type="button" data-community-like class="${Number(post.curtiu)?'is-active':''}" aria-label="Curtir publicação"><i class="fa-${Number(post.curtiu)?'solid':'regular'} fa-heart"></i><span>${Number(post.total_curtidas)}</span></button><button type="button" data-community-comments aria-label="Abrir comentários"><i class="fa-regular fa-comment"></i><span>${Number(post.total_comentarios)}</span></button><button type="button" data-community-share aria-label="Compartilhar publicação"><i class="fa-solid fa-arrow-up-from-bracket"></i><span>Compartilhar</span></button></footer><section class="community-comments" hidden></section></article>`}
function communityCommentTree(comments){const grouped=new Map();comments.forEach(comment=>{const parent=Number(comment.id_comentario_pai)||0;if(!grouped.has(parent))grouped.set(parent,[]);grouped.get(parent).push(comment)});const render=comment=>`<article class="community-comment" data-community-comment="${Number(comment.id_comentario)}"><header><span><a href="perfil.php?id=${Number(comment.id_usuario)}">${esc(comment.nm_usuario)}</a>${communityRoleBadge(comment.papel_comunidade)}</span><time>${esc(comment.criado_em)}</time></header><p>${esc(comment.conteudo)}</p><div class="community-comment-actions"><button type="button" data-community-comment-like class="${Number(comment.curtiu)?'is-active':''}"><i class="fa-${Number(comment.curtiu)?'solid':'regular'} fa-heart"></i><span>${Number(comment.total_curtidas)}</span></button><button type="button" data-community-comment-reply><i class="fa-solid fa-reply"></i>Responder</button></div><form data-community-reply-form hidden><input name="text" maxlength="1200" placeholder="Responder a ${esc(comment.nm_usuario)}" required><button class="ui-button" aria-label="Enviar resposta"><i class="fa-solid fa-paper-plane"></i></button></form><div class="community-comment-children">${(grouped.get(Number(comment.id_comentario))||[]).map(render).join('')}</div></article>`;return (grouped.get(0)||[]).map(render).join('')}
async function refreshCommunityComments(post,id){const box=post.querySelector('.community-comments'),result=await api('comments',{query:{post:id}});box.innerHTML=`<div class="community-comment-list">${communityCommentTree(result.comments)||'<p class="community-comments-empty">Nenhum comentário ainda.</p>'}</div><form data-community-comment-form><input name="text" maxlength="1200" placeholder="Escreva um comentário" required><button class="ui-button" aria-label="Enviar comentário"><i class="fa-solid fa-paper-plane"></i></button></form>`;box.hidden=false;post.querySelector('[data-community-comments] span').textContent=result.comments.length;return result.comments.length}
async function openCommunity(id){if(source)source.close();clearInterval(messageSync);source=null;messageSync=null;activeChat=0;const joined=await api('join_community',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,id})}});if(joined.status==='pendente'){showChatNotice(joined.message,'Solicitação enviada');return}const result=await api('feed',{query:{community:id}});activeCommunity={...result.community,role:result.role,canManage:result.canManage,canModerate:result.canModerate};chatTitle.textContent=activeCommunity.nome;communityManageButton.hidden=!result.canModerate;communityManageButton.innerHTML=result.canManage?'<i class="fa-solid fa-gear"></i>Gerenciar':'<i class="fa-solid fa-shield-halved"></i>Moderar';setView('communityView');
communityView.innerHTML=`<div class="community-stream" id="communityStream"><article class="community-hero ui-card"><div class="community-hero__identity">${communityAvatar(activeCommunity,'community-profile-image')}<div><h2>${esc(activeCommunity.nome)}</h2><p>${esc(activeCommunity.descricao)}</p><small>${Number(activeCommunity.membros)} membro(s) · ${activeCommunity.privada==1?'Privada':'Pública'}</small></div></div></article><div class="community-post-list">${result.posts.map(renderCommunityPost).join('')||'<div class="social-empty">Nenhuma publicação ainda.</div>'}</div></div><form class="post-composer post-composer--community ui-card" id="communityPost" enctype="multipart/form-data"><label for="communityMessage">Criar publicação</label><textarea id="communityMessage" name="text" maxlength="4000" placeholder="Compartilhe algo com a comunidade"></textarea><div class="selected-media-preview" id="communityMediaPreview" hidden></div><div class="post-composer__actions"><label class="community-media-button"><i class="fa-regular fa-image"></i>Foto ou vídeo<input id="communityMediaInput" type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4" hidden></label><span class="community-post-status" role="status"></span><button class="ui-button" type="submit">Publicar</button></div></form>`;const form=document.getElementById('communityPost'),mediaInput=document.getElementById('communityMediaInput'),mediaPreview=document.getElementById('communityMediaPreview');bindPreview(mediaInput,mediaPreview,true);form.addEventListener('submit',async event=>{event.preventDefault();const status=form.querySelector('.community-post-status'),formData=new FormData(form);status.textContent='Publicando...';formData.append('csrf',CSRF);formData.append('community',id);try{await api('post',{fetch:{method:'POST',body:formData}});await openCommunity(id)}catch(error){status.textContent=error.message}});
communityView.onclick=async event=>{const post=event.target.closest('[data-community-post]');if(!post)return;const postId=Number(post.dataset.communityPost),edit=event.target.closest('[data-edit-community-post]'),remove=event.target.closest('[data-delete-community-post]'),like=event.target.closest('[data-community-like]'),comments=event.target.closest('[data-community-comments]'),share=event.target.closest('[data-community-share]'),reply=event.target.closest('[data-community-comment-reply]'),commentLike=event.target.closest('[data-community-comment-like]');
try{if(edit){const current=post.querySelector(':scope > p')?.textContent||'';openEditor('edit_post',postId,current,()=>openCommunity(id));return}
if(remove){if(!await askConfirmation('Esta publicação e todos os comentários serão excluídos permanentemente.','Excluir publicação'))return;await api('delete_community_post',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:postId})}});post.remove();showChatNotice('Publicação excluída.','Moderação');return}
if(like){const response=await api('toggle_like',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:postId})}});like.classList.toggle('is-active',response.liked);like.querySelector('i').className=`fa-${response.liked?'solid':'regular'} fa-heart`;like.querySelector('span').textContent=response.count;return}if(comments){const box=post.querySelector('.community-comments');if(!box.hidden){box.hidden=true;return}await refreshCommunityComments(post,postId);return}if(share){const url=location.origin+location.pathname+'#community-post-'+postId;if(navigator.share)await navigator.share({title:activeCommunity.nome,url});else{await navigator.clipboard.writeText(url);showChatNotice('Link da publicação copiado.','Compartilhar')}return}if(reply){const replyForm=reply.closest('[data-community-comment]').querySelector(':scope > [data-community-reply-form]');replyForm.hidden=!replyForm.hidden;if(!replyForm.hidden)replyForm.elements.text.focus();return}if(commentLike){const comment=commentLike.closest('[data-community-comment]');const response=await api('toggle_comment_like',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:postId,comment:comment.dataset.communityComment})}});commentLike.classList.toggle('is-active',response.liked);commentLike.querySelector('i').className=`fa-${response.liked?'solid':'regular'} fa-heart`;commentLike.querySelector('span').textContent=response.count}}catch(error){showChatNotice(error.message,'Não foi possível concluir')}};communityView.onsubmit=async event=>{const commentForm=event.target.closest('[data-community-comment-form],[data-community-reply-form]');if(!commentForm)return;event.preventDefault();const post=commentForm.closest('[data-community-post]'),postId=Number(post.dataset.communityPost),parent=commentForm.matches('[data-community-reply-form]')?Number(commentForm.closest('[data-community-comment]').dataset.communityComment):0,button=commentForm.querySelector('button');button.disabled=true;try{await api('add_comment',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:postId,parent,text:commentForm.elements.text.value})}});await refreshCommunityComments(post,postId)}catch(error){showChatNotice(error.message,'Não foi possível comentar')}finally{button.disabled=false}}}

async function openChat(id,title){activeCommunity=null;communityManageButton.hidden=true;activeChat=id;clearReply();chatTitle.textContent=title;setView('chatView');messages.innerHTML='';if(source)source.close();clearInterval(messageSync);const result=await api('messages',{query:{chat:id}});result.messages.forEach(addMessage);source=new EventSource(EVENTS+'?'+new URLSearchParams({chat:id,after:lastMessage()}));source.addEventListener('message',event=>addMessage(JSON.parse(event.data)));messageSync=setInterval(async()=>{if(activeChat!==id)return;try{const current=await api('messages',{query:{chat:id}});if(activeChat===id)current.messages.forEach(addMessage)}catch(error){}},8000)}
function lastMessage(){return Number(messages.lastElementChild?.dataset.id||0)}
function addMessage(message){if(Number(message.id_chat)!==activeChat)return;let element=messages.querySelector(`[data-id="${message.id_mensagem}"]`);const mine=Number(message.id_usuario)===ME;const quote=message.id_mensagem_resposta?`<button class="message-quote" type="button" data-jump-message="${Number(message.id_mensagem_resposta)}"><strong>${esc(message.resposta_autor||'Mensagem')}</strong><span>${esc(message.resposta_texto||((message.resposta_tipo_anexo&&message.resposta_tipo_anexo!=='nenhum')?'Mídia':'Mensagem indisponível'))}</span></button>`:'';const body=`<div class="message-head">${!mine&&message.foto_perfil?`<img class="message-avatar" src="${esc(message.foto_perfil)}" alt="">`:''}<strong>${esc(message.nm_usuario)}</strong><span class="message-tools"><button type="button" data-reply-message aria-label="Responder mensagem"><i class="fa-solid fa-reply"></i></button>${mine&&message.texto?'<button type="button" data-edit-message aria-label="Editar mensagem"><i class="fa-solid fa-pen"></i></button>':''}</span></div>${quote}${message.anexo_url?`<img src="${esc(message.anexo_url)}" alt="${message.tipo_anexo==='sticker'?'Figurinha':'Imagem enviada'}">`:''}${message.texto?`<p>${esc(message.texto)}</p>`:''}<small class="message-time">${esc(message.criado_em||'')}${message.editado_em?' · editada':''}</small>`;if(element){element.innerHTML=body;return}element=document.createElement('article');element.className='message '+(mine?'is-mine ':'')+(message.tipo_anexo==='sticker'?'is-sticker':'');element.dataset.id=message.id_mensagem;element.dataset.author=message.nm_usuario||'Usuário';element.dataset.text=message.texto||((message.tipo_anexo&&message.tipo_anexo!=='nenhum')?'Mídia':'Mensagem');element.innerHTML=body;messages.appendChild(element);messages.scrollTop=messages.scrollHeight}
function clearReply(){replyingTo=null;replyPreview.hidden=true;replyAuthor.textContent='';replyText.textContent=''}
messageForm.addEventListener('submit',async event=>{event.preventDefault();if(!activeChat)return;const file=stickerInput.files[0]||imageInput.files[0],formData=new FormData();formData.append('csrf',CSRF);formData.append('chat',activeChat);formData.append('text',messageText.value);formData.append('kind',stickerInput.files[0]?'sticker':'imagem');if(replyingTo)formData.append('reply_to',replyingTo.id);if(file)formData.append('media',file);await api('send',{fetch:{method:'POST',body:formData}});messageText.value='';imageInput.value='';stickerInput.value='';clearPreview(messagePreview);clearReply()});
messageText.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();messageForm.requestSubmit()}});
messages.addEventListener('click',event=>{const jump=event.target.closest('[data-jump-message]');if(jump){const target=messages.querySelector(`[data-id="${jump.dataset.jumpMessage}"]`);if(target){target.scrollIntoView({behavior:'smooth',block:'center'});target.classList.add('is-highlighted');setTimeout(()=>target.classList.remove('is-highlighted'),1400)}return}const reply=event.target.closest('[data-reply-message]');if(reply){const message=reply.closest('[data-id]');replyingTo={id:Number(message.dataset.id),author:message.dataset.author,text:message.dataset.text};replyAuthor.textContent='Respondendo a '+replyingTo.author;replyText.textContent=replyingTo.text;replyPreview.hidden=false;messageText.focus();return}const button=event.target.closest('[data-edit-message]');if(!button)return;const message=button.closest('[data-id]'),current=message.querySelector('p')?.textContent||'';openEditor('edit_message',message.dataset.id,current,result=>{const paragraph=message.querySelector('p');if(paragraph)paragraph.textContent=result.text;message.dataset.text=result.text;const time=message.querySelector('.message-time');if(time&&!time.textContent.includes('editada'))time.textContent+=' · editada'})});
cancelReply.addEventListener('click',clearReply);

function clearPreview(container){container.innerHTML='';container.hidden=true}
function bindPreview(input,container,allowVideo=false,onSelected){input.addEventListener('change',()=>{clearPreview(container);const file=input.files?.[0];if(!file)return;if(file.size>40*1024*1024){input.value='';container.hidden=false;container.textContent='O arquivo excede o limite permitido.';return}const url=URL.createObjectURL(file),isVideo=allowVideo&&file.type.startsWith('video/');container.innerHTML=`${isVideo?`<video src="${url}" controls></video>`:`<img src="${url}" alt="Prévia da mídia selecionada">`}<button type="button" aria-label="Remover mídia"><i class="fa-solid fa-xmark"></i></button>`;container.hidden=false;container.querySelector('button').onclick=()=>{input.value='';URL.revokeObjectURL(url);clearPreview(container)};if(onSelected)onSelected()})}
bindPreview(imageInput,messagePreview,false,()=>{stickerInput.value=''});bindPreview(stickerInput,messagePreview,false,()=>{imageInput.value=''});

globalSearch.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(globalSearch.value.trim().length<2){searchResults.innerHTML='';return}const result=await api('search',{query:{q:globalSearch.value}});searchResults.innerHTML=[...result.communities.map(community=>`<button class="social-item" type="button" data-search-community="${community.id_comunidade}">${communityAvatar(community)}<span class="social-item__body"><strong>${esc(community.nome)}</strong><small>Comunidade ${community.privada==1?'privada':'pública'}</small></span></button>`),...result.users.map(user=>`<button class="social-item" type="button" data-search-user="${user.id_usuario}" data-user-name="${esc(user.nm_usuario)}">${avatar(user.foto_perfil,user.nm_usuario)}<span class="social-item__body"><strong>${esc(user.nm_usuario)}</strong><small>Usuário do LibrasHub</small></span></button>`)].join('')},250)});
searchResults.addEventListener('click',async event=>{const community=event.target.closest('[data-search-community]'),user=event.target.closest('[data-search-user]');if(community){tab='communities';renderList();await openCommunity(Number(community.dataset.searchCommunity))}if(user){const result=await api('start_private',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,user:user.dataset.searchUser})}});tab='private';await overview();renderList();await openChat(result.id,user.dataset.userName)}searchResults.innerHTML=''});
function openEditor(action,id,text,done){editContext={action,id,done};editDialogTitle.textContent=action==='edit_message'?'Editar mensagem':'Editar publicação';editText.value=text;editStatus.textContent='';editDialog.classList.add('is-open');setTimeout(()=>editText.focus(),0)}
editForm.addEventListener('submit',async event=>{event.preventDefault();if(!editContext)return;const submit=event.target.querySelector('[type="submit"]'),payload={csrf:CSRF,text:editText.value};payload[editContext.action==='edit_post'?'post':'message']=editContext.id;submit.disabled=true;editStatus.textContent='Salvando...';try{const result=await api(editContext.action,{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}}),done=editContext.done;editDialog.classList.remove('is-open');editContext=null;await done(result)}catch(error){editStatus.textContent=error.message}finally{submit.disabled=false}});

