createCommunity.addEventListener('click',()=>{communityStatus.textContent='';communityDialog.classList.add('is-open')});bindPreview(communityImage,communityCreatePreview);
communityForm.addEventListener('submit',async event=>{event.preventDefault();const formData=new FormData(event.target);formData.append('csrf',CSRF);communityStatus.textContent='Criando...';try{const result=await api('create_community',{fetch:{method:'POST',body:formData}});event.target.reset();clearPreview(communityCreatePreview);communityDialog.classList.remove('is-open');tab='communities';await overview();await openCommunity(Number(result.id))}catch(error){communityStatus.textContent=error.message}});
