communityManageButton.addEventListener('click',openManagement);bindPreview(manageImage,manageImagePreview);
async function openManagement(){if(!activeCommunity?.canModerate)return;const isOwner=Boolean(activeCommunity.canManage);document.querySelectorAll('[data-owner-only]').forEach(element=>element.hidden=!isOwner);manageDialogTitle.textContent=isOwner?'Gerenciar comunidade':'Moderar comunidade';membersHelp.textContent=isOwner?'Defina moderadores, aprove solicitações ou expulse participantes.':'Fiscalize os membros e expulse usuários comuns quando necessário.';memberView=isOwner?'requests':'members';if(isOwner){manageName.value=activeCommunity.nome;manageDescription.value=activeCommunity.descricao;managePrivate.checked=Number(activeCommunity.privada)===1;manageImage.value='';clearPreview(manageImagePreview)}manageStatus.textContent='';memberStatus.textContent='';manageDialog.classList.add('is-open');await loadMembers()}
function renderMembers(){const owner=Boolean(activeCommunity?.canManage),filtered=communityMembers.filter(member=>memberView==='requests'?member.status==='pendente':member.status!=='pendente');requestCount.textContent=String(communityMembers.filter(member=>member.status==='pendente').length);document.querySelectorAll('[data-member-view]').forEach(button=>button.classList.toggle('is-active',button.dataset.memberView===memberView));communityMemberList.innerHTML=filtered.map(member=>{let actions='';if(member.status==='pendente'&&owner)actions=`<button type="button" class="member-action member-action--approve" data-approve-member="${member.id_usuario}">Aprovar</button><button type="button" class="member-action member-action--remove" data-reject-member="${member.id_usuario}">Recusar</button>`;else if(member.papel==='membro')actions=`${owner?`<button type="button" class="member-action member-action--role" data-set-role="moderador" data-user="${member.id_usuario}"><i class="fa-solid fa-shield-halved"></i>Tornar moderador</button>`:''}<button type="button" class="member-action member-action--remove" data-remove-member="${member.id_usuario}">Expulsar</button>`;else if(member.papel==='moderador'&&owner)actions=`<button type="button" class="member-action" data-set-role="membro" data-user="${member.id_usuario}">Remover moderação</button><button type="button" class="member-action member-action--remove" data-remove-member="${member.id_usuario}">Expulsar</button>`;return `<article class="community-member">${avatar(member.foto_perfil,member.nm_usuario,'member-avatar')}<div><strong>${esc(member.nm_usuario)} ${communityRoleBadge(member.papel)}</strong><small>${esc(member.status)}</small></div><div class="member-actions">${actions}</div></article>`}).join('')||`<div class="social-empty">${memberView==='requests'?'Nenhuma solicitação pendente.':'Nenhum membro nesta lista.'}</div>`}
async function loadMembers(){if(!activeCommunity)return;communityMemberList.innerHTML='<div class="social-empty">Carregando membros...</div>';try{const result=await api('community_members',{query:{community:activeCommunity.id_comunidade}});communityMembers=result.members;renderMembers()}catch(error){communityMemberList.innerHTML=`<div class="ui-alert ui-alert--error">${esc(error.message)}</div>`}}
manageForm.addEventListener('submit',async event=>{event.preventDefault();if(!activeCommunity)return;const id=Number(activeCommunity.id_comunidade),formData=new FormData(event.target);formData.append('csrf',CSRF);formData.append('community',id);manageStatus.textContent='Salvando...';try{await api('update_community',{fetch:{method:'POST',body:formData}});await overview();await openCommunity(id);manageDialog.classList.add('is-open');manageStatus.textContent='Informações atualizadas.'}catch(error){manageStatus.textContent=error.message}});
memberAddForm.addEventListener('submit',async event=>{event.preventDefault();memberStatus.textContent='Adicionando...';try{await api('add_community_member',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,community:activeCommunity.id_comunidade,handle:memberHandle.value})}});event.target.reset();memberStatus.textContent='Membro adicionado.';await loadMembers()}catch(error){memberStatus.textContent=error.message}});
document.querySelector('.member-view-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-member-view]');if(!button)return;memberView=button.dataset.memberView;renderMembers()});
communityMemberList.addEventListener('click',async event=>{const approve=event.target.closest('[data-approve-member]'),reject=event.target.closest('[data-reject-member]'),remove=event.target.closest('[data-remove-member]'),roleButton=event.target.closest('[data-set-role]');if(!approve&&!reject&&!remove&&!roleButton)return;const action=roleButton?'set_community_role':approve?'approve_community_member':reject?'reject_community_member':'remove_community_member',user=Number(roleButton?roleButton.dataset.user:approve?approve.dataset.approveMember:reject?reject.dataset.rejectMember:remove.dataset.removeMember);if((reject||remove)&&!await askConfirmation(reject?'Recusar esta solicitação de entrada?':'Expulsar este usuário da comunidade?',reject?'Recusar solicitação':'Expulsar membro'))return;const buttons=event.target.closest('.member-actions')?.querySelectorAll('button')||[];buttons.forEach(button=>button.disabled=true);memberStatus.textContent='Processando...';try{const payload={csrf:CSRF,community:activeCommunity.id_comunidade,user};if(roleButton)payload.role=roleButton.dataset.setRole;const result=await api(action,{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}});memberStatus.textContent=result.message;await loadMembers();await overview()}catch(error){memberStatus.textContent=error.message;buttons.forEach(button=>button.disabled=false)}});
document.addEventListener('click',event=>{const close=event.target.closest('[data-close]');if(close)close.closest('.social-dialog')?.classList.remove('is-open');if(event.target.classList.contains('social-dialog'))event.target.classList.remove('is-open')});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(confirmDialog.classList.contains('is-open'))closeConfirmation(false);document.querySelectorAll('.social-dialog.is-open').forEach(dialog=>dialog.classList.remove('is-open'))}});
overview();
